#!/usr/bin/env python3
from __future__ import annotations
import json, shutil, subprocess, tempfile, time
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'evidence/generated'; OUT.mkdir(parents=True,exist_ok=True)
MUTANTS=[
 ('reviewer-self-issuance-bypass','src/security/reviewer-trust.js',"if (payload.issuerId === payload.reviewerKeyId)\n            throw new Error('reviewer_credential_self_issuance_forbidden');","if (false && payload.issuerId === payload.reviewerKeyId)\n            throw new Error('reviewer_credential_self_issuance_forbidden');",'tests/credential-issuer-roast-v32.test.js','registered keys cannot self-issue reviewer or provider credentials'),
 ('provider-self-issuance-bypass','src/security/provider-trust.js',"if (payload.issuerId === payload.providerKeyId)\n            throw new Error('provider_credential_self_issuance_forbidden');","if (false && payload.issuerId === payload.providerKeyId)\n            throw new Error('provider_credential_self_issuance_forbidden');",'tests/credential-issuer-roast-v32.test.js','registered keys cannot self-issue reviewer or provider credentials'),
 ('issuer-root-authorization-bypass','src/security/credential-issuer-trust.js',"if (!this.trustedRootKeyIds.has(grant.issuerKeyId) || payload.rootAuthorityId !== grant.issuerKeyId)","if (false && (!this.trustedRootKeyIds.has(grant.issuerKeyId) || payload.rootAuthorityId !== grant.issuerKeyId))",'tests/credential-issuer-roast-v32.test.js','only a trusted root can authorize a credential issuer and grant scope cannot be exceeded'),
 ('exact-grant-digest-binding-bypass','src/security/credential-issuer-trust.js',"const grant = this.#grantsByDigest.get(input.grantDigest);","const grant = this.#grantsByDigest.get(input.grantDigest) ?? this.#grantsByDigest.values().next().value;",'tests/credential-issuer-roast-v32.test.js','credential binds to the exact root-issued grant digest'),
 ('grant-revocation-bypass','src/security/credential-issuer-trust.js',"if (revocation !== undefined && at >= Date.parse(revocation.payload.revokedAt))\n            throw new Error('credential_issuer_grant_revoked');","if (false && revocation !== undefined && at >= Date.parse(revocation.payload.revokedAt))\n            throw new Error('credential_issuer_grant_revoked');",'tests/credential-issuer-roast-v32.test.js','revoking an issuer grant prevents later issuer authorization without rewriting existing grant evidence'),
 ('reviewer-acceptance-time-signature-bypass','src/security/reviewer-trust.js',"if (!keyRegistry.verifyAt(credential, payload.issuedAt) || (acceptedAt !== undefined && !keyRegistry.verifyAt(credential, acceptedAt)))","if (!keyRegistry.verifyAt(credential, payload.issuedAt) || false && (acceptedAt !== undefined && !keyRegistry.verifyAt(credential, acceptedAt)))",'tests/credential-key-revocation-v32.test.js','credential submitted after issuer-key revocation is rejected even when backdated'),
 ('provider-acceptance-time-signature-bypass','src/security/provider-trust.js',"if (!keyRegistry.verifyAt(credential, payload.issuedAt) || (acceptedAt !== undefined && !keyRegistry.verifyAt(credential, acceptedAt)))","if (!keyRegistry.verifyAt(credential, payload.issuedAt) || false && (acceptedAt !== undefined && !keyRegistry.verifyAt(credential, acceptedAt)))",'tests/credential-key-revocation-v32.test.js','provider credential submitted after issuer-key revocation is rejected even when backdated'),
 ('time-effective-key-revocation-bypass','src/contracts/crypto.js',"if (revokedAt !== undefined && Date.parse(revokedAt) <= parsed)","if (false && revokedAt !== undefined && Date.parse(revokedAt) <= parsed)",'tests/credential-key-revocation-v32.test.js','time-effective key revocation preserves historical verification while blocking current trust'),
 ('revocation-export-time-drop','src/contracts/crypto.js',"...(revokedAt === undefined ? {} : { revokedAt })","...(revokedAt === undefined ? {} : {})",'tests/credential-key-revocation-v32.test.js','export and import preserve the effective revocation timestamp'),
 ('root-custodian-threshold-bypass','src/platform/credential-trust-bundle.js',"if (new Set([...signersById.keys()].map((keyId) => custodians[keyId])).size < input.rootPolicy.threshold)","if (false && new Set([...signersById.keys()].map((keyId) => custodians[keyId])).size < input.rootPolicy.threshold)",'tests/credential-trust-bundle-branch-v32.test.js','bundle creation rejects malformed identity, policy, signer set and unavailable roots'),
 ('root-custodian-pin-bypass','src/platform/credential-trust-bundle.js',"if (Object.values(pinnedCustodians).some((value) => typeof value !== 'string' || value.trim() === '') || sha256(pinnedCustodians) !== sha256(bundle.payload.rootPolicy.custodianIdsByRootKeyId))","if (false && (Object.values(pinnedCustodians).some((value) => typeof value !== 'string' || value.trim() === '') || sha256(pinnedCustodians) !== sha256(bundle.payload.rootPolicy.custodianIdsByRootKeyId)))",'tests/credential-trust-bundle-v32.test.js','root fingerprint, public key and payload substitutions are rejected'),
 ('root-fingerprint-pin-bypass','src/platform/credential-trust-bundle.js',"if (!/^[0-9a-f]{64}$/.test(pinnedFingerprint) || preRevocationRegistry.fingerprint(rootKeyId) !== pinnedFingerprint)","if (false && (!/^[0-9a-f]{64}$/.test(pinnedFingerprint) || preRevocationRegistry.fingerprint(rootKeyId) !== pinnedFingerprint))",'tests/credential-trust-bundle-v32.test.js','root fingerprint, public key and payload substitutions are rejected'),
 ('root-signature-threshold-bypass','src/platform/credential-trust-bundle.js',"if (validRootSigners.size < pinnedRoots.threshold)\n        throw new Error('credential_trust_signature_threshold_not_met');","if (false && validRootSigners.size < pinnedRoots.threshold)\n        throw new Error('credential_trust_signature_threshold_not_met');",'tests/credential-trust-bundle-v32.test.js','bundle requires the externally pinned threshold and exact root set'),
 ('bundle-predecessor-bypass','src/platform/credential-trust-bundle.js',"if (bundle.payload.predecessorBundleDigest !== priorDigest)\n                    throw new Error('credential_trust_bundle_predecessor_mismatch');","if (false && bundle.payload.predecessorBundleDigest !== priorDigest)\n                    throw new Error('credential_trust_bundle_predecessor_mismatch');",'tests/credential-trust-bundle-v32.test.js','file trust store persists, reloads and enforces predecessor monotonicity against rollback and forks'),
 ('anchor-current-bypass','src/platform/credential-trust-bundle.js',"if (current === undefined ? bundleDigest !== undefined : current.bundleDigest !== bundleDigest)\n            throw new Error('credential_trust_anchor_mismatch');","if (false && (current === undefined ? bundleDigest !== undefined : current.bundleDigest !== bundleDigest))\n            throw new Error('credential_trust_anchor_mismatch');",'tests/credential-trust-bundle-v32.test.js','independent anchor detects replacement of the trust bundle with an older valid signed bundle after restart'),
 ('pending-intent-digest-bypass','src/platform/credential-trust-bundle.js',"if (intentDigest !== sha256(intentMaterial) || credentialTrustBundleDigest(pending.bundle) !== pending.nextBundleDigest || pending.bundle.payload.bundleId !== pending.bundleId || pending.bundle.payload.generatedAt !== pending.generatedAt || pending.bundle.payload.predecessorBundleDigest !== pending.priorBundleDigest)","if (false && (intentDigest !== sha256(intentMaterial) || credentialTrustBundleDigest(pending.bundle) !== pending.nextBundleDigest || pending.bundle.payload.bundleId !== pending.bundleId || pending.bundle.payload.generatedAt !== pending.generatedAt || pending.bundle.payload.predecessorBundleDigest !== pending.priorBundleDigest))",'tests/credential-trust-bundle-v32.test.js','pending journal tampering and contradictory file-anchor state fail closed'),
]
records=[]
for mid,target,old,new,test,marker in MUTANTS:
    start=time.perf_counter(); temp=Path(tempfile.mkdtemp(prefix=f'v32-mut-{mid}-'))
    try:
        shutil.copytree(ROOT/'dist',temp/'dist')
        path=temp/'dist'/target; text=path.read_text(); count=text.count(old)
        if count!=1:
            records.append({'mutantId':mid,'status':'not-created','matchCount':count,'target':target}); continue
        path.write_text(text.replace(old,new,1))
        try:
            p=subprocess.run(['node','--test',f'dist/{test}'],cwd=temp,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=90)
            observed=marker in p.stdout
            status='killed-authentic' if p.returncode!=0 and observed else ('survived' if p.returncode==0 else 'invalid-kill')
            records.append({'mutantId':mid,'target':target,'test':test,'expectedFailureMarker':marker,'markerObserved':observed,'exitCode':p.returncode,'status':status,'durationMs':round((time.perf_counter()-start)*1000,3),'outputTail':p.stdout[-3000:]})
        except subprocess.TimeoutExpired as exc:
            output=(exc.stdout or '') if isinstance(exc.stdout,str) else ''
            records.append({'mutantId':mid,'target':target,'test':test,'expectedFailureMarker':marker,'markerObserved':marker in output,'exitCode':None,'status':'invalid-kill','durationMs':round((time.perf_counter()-start)*1000,3),'outputTail':output[-3000:],'reason':'timeout_is_not_a_kill'})
    finally: shutil.rmtree(temp,ignore_errors=True)
passed=len(records)==len(MUTANTS) and all(r['status']=='killed-authentic' for r in records)
report={'version':'32.0','status':'passed' if passed else 'failed','classification':'targeted-credential-sovereignty-roast-mutation-with-dedicated-failure-markers','mutantsSpecified':len(MUTANTS),'mutantsKilledAuthentically':sum(r['status']=='killed-authentic' for r in records),'survivors':sum(r['status']=='survived' for r in records),'invalidKills':sum(r['status'] in ('invalid-kill','not-created') for r in records),'records':records,'limitations':['Targeted v32 mutations supplement rather than replace retained v22-v31 mutation portfolios.','A mutation is accepted only when its dedicated behavioral test title appears in a nonzero result; timeouts and generic failures are invalid kills.']}
(OUT/'V32_CREDENTIAL_SOVEREIGNTY_MUTATION_RESULTS.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({k:report[k] for k in ('status','mutantsSpecified','mutantsKilledAuthentically','survivors','invalidKills')},indent=2))
raise SystemExit(0 if passed else 1)
